require_once __DIR__.'/_layout.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$s=$pdo->prepare("UPDATE inquiries SET status='resolved' WHERE inquiry_id=?");$s->execute([(int)$_POST['id']]);flash('success','Inquiry marked resolved.');redirect('inquiries.php');}$items=$pdo->query('SELECT * FROM inquiries ORDER BY created_at DESC')->fetchAll();admin_start('Guest correspondence');?><table class="data-table"><thead><tr><th>Received</th><th>From</th><th>Subject & message</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= e($i['created_at']) ?></td><td><?= e($i['name']) ?><br><?= e($i['email']) ?></td><td><strong><?= e($i['subject']) ?></strong><br><?= nl2br(e($i['message'])) ?></td><td><?= e($i['status']) ?></td><td><?php if($i['status']!=='resolved'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$i['inquiry_id'] ?>"><button class="button button-small">Resolve</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php admin_end(); ?>
